
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY,checksum TEXT NOT NULL,applied_at INTEGER NOT NULL);
CREATE TABLE database_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE objects(id TEXT PRIMARY KEY,kind TEXT NOT NULL,project_id TEXT REFERENCES projects(id),revision INTEGER NOT NULL CHECK(revision>0),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,archived_at INTEGER,UNIQUE(id,kind),UNIQUE(id,project_id));
CREATE TABLE devices(id TEXT PRIMARY KEY,name TEXT NOT NULL,environment TEXT NOT NULL,credential_ref TEXT,last_seen_at INTEGER);
CREATE TABLE actors(id TEXT PRIMARY KEY,kind TEXT NOT NULL,provider TEXT,identity_ref TEXT,authority_id TEXT REFERENCES actors(id));
CREATE TABLE project_locations(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),device_id TEXT NOT NULL REFERENCES devices(id),root_path TEXT NOT NULL,status TEXT NOT NULL,UNIQUE(id,project_id));
CREATE UNIQUE INDEX active_project_location ON project_locations(device_id,root_path) WHERE status='active';
CREATE TABLE contents(id TEXT PRIMARY KEY,sha256 TEXT NOT NULL CHECK(length(sha256)=64),mime_type TEXT NOT NULL,encoding TEXT NOT NULL,byte_length INTEGER NOT NULL CHECK(byte_length>=0),stored_byte_length INTEGER NOT NULL CHECK(stored_byte_length>=0),data BLOB NOT NULL,chunk_index_json TEXT,CHECK((encoding LIKE 'chunked:%' AND length(data)=0 AND chunk_index_json IS NOT NULL) OR (encoding NOT LIKE 'chunked:%' AND length(data)=stored_byte_length AND chunk_index_json IS NULL)),UNIQUE(sha256,mime_type,encoding));
CREATE TABLE content_chunks(content_id TEXT NOT NULL REFERENCES contents(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),data BLOB NOT NULL CHECK(length(data)>0 AND length(data)<=65536),PRIMARY KEY(content_id,ordinal));
CREATE TABLE object_revisions(object_id TEXT NOT NULL REFERENCES objects(id),revision INTEGER NOT NULL,content_id TEXT NOT NULL REFERENCES contents(id),actor_id TEXT NOT NULL REFERENCES actors(id),reason TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(object_id,revision));
CREATE TABLE relations(source_id TEXT NOT NULL REFERENCES objects(id),relation TEXT NOT NULL,target_id TEXT NOT NULL REFERENCES objects(id),PRIMARY KEY(source_id,relation,target_id));
CREATE TABLE migration_items(source_identity TEXT NOT NULL,source_key TEXT NOT NULL,source_hash TEXT NOT NULL,object_id TEXT REFERENCES objects(id),imported_revision INTEGER,stage TEXT NOT NULL,error TEXT,source_content_id TEXT REFERENCES contents(id),source_capture_revision INTEGER NOT NULL DEFAULT 0 CHECK(source_capture_revision>=0),source_capture_request_id TEXT REFERENCES requests(id),PRIMARY KEY(source_identity,source_key));
CREATE TABLE roadmap_dependencies(node_id TEXT NOT NULL REFERENCES roadmap_nodes(id),dependency_id TEXT NOT NULL REFERENCES roadmap_nodes(id),PRIMARY KEY(node_id,dependency_id));
CREATE TABLE session_bindings(conversation_id TEXT NOT NULL REFERENCES conversations(id),binding_revision INTEGER NOT NULL,provider TEXT NOT NULL,native_session_id TEXT,state TEXT NOT NULL,contract TEXT,evidence_id TEXT REFERENCES evidence(id),provider_context_content_id TEXT REFERENCES contents(id),PRIMARY KEY(conversation_id,binding_revision));
CREATE TABLE log_chunks(run_id TEXT NOT NULL REFERENCES runs(id),stream TEXT NOT NULL,sequence INTEGER NOT NULL,content_id TEXT NOT NULL REFERENCES contents(id),recorded_at INTEGER NOT NULL,byte_offset INTEGER NOT NULL,PRIMARY KEY(run_id,stream,sequence));
CREATE TABLE run_changes(run_id TEXT NOT NULL REFERENCES runs(id),relative_path TEXT NOT NULL,role TEXT NOT NULL,change_kind TEXT,before_content_id TEXT REFERENCES contents(id),after_content_id TEXT REFERENCES contents(id),PRIMARY KEY(run_id,relative_path,role));
CREATE TABLE run_summaries(run_id TEXT PRIMARY KEY REFERENCES runs(id),summary_content_id TEXT REFERENCES contents(id),handoff_content_id TEXT REFERENCES contents(id),source_revision INTEGER NOT NULL);
CREATE TABLE ui_state(device_id TEXT NOT NULL REFERENCES devices(id),view TEXT NOT NULL,scope_key TEXT NOT NULL,key TEXT NOT NULL,value_json TEXT NOT NULL,revision INTEGER NOT NULL,PRIMARY KEY(device_id,view,scope_key,key));
CREATE TABLE leases(resource_id TEXT NOT NULL REFERENCES objects(id),purpose TEXT NOT NULL,owner_runtime_id TEXT NOT NULL REFERENCES runtime_instances(id),generation INTEGER NOT NULL,expires_at INTEGER NOT NULL,PRIMARY KEY(resource_id,purpose));
CREATE TABLE schedule_firings(schedule_id TEXT NOT NULL REFERENCES schedules(id),occurrence_key TEXT NOT NULL,task_id TEXT NOT NULL REFERENCES tasks(id),status TEXT NOT NULL,PRIMARY KEY(schedule_id,occurrence_key));
CREATE TABLE events(id TEXT PRIMARY KEY,sequence INTEGER NOT NULL UNIQUE,subject_id TEXT REFERENCES objects(id),actor_id TEXT NOT NULL REFERENCES actors(id),kind TEXT NOT NULL,content_id TEXT NOT NULL REFERENCES contents(id),created_at INTEGER NOT NULL,request_id TEXT NOT NULL REFERENCES requests(id));
CREATE TABLE requests(actor_id TEXT NOT NULL REFERENCES actors(id),idempotency_key TEXT NOT NULL,id TEXT NOT NULL UNIQUE,input_hash TEXT NOT NULL,result_content_id TEXT REFERENCES contents(id),status TEXT NOT NULL,committed_sequence INTEGER,PRIMARY KEY(actor_id,idempotency_key));
CREATE TABLE outbox(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id),channel TEXT NOT NULL,destination_ref TEXT NOT NULL,content_id TEXT NOT NULL REFERENCES contents(id),generation INTEGER NOT NULL,state TEXT NOT NULL,attempt INTEGER NOT NULL DEFAULT 0,next_attempt_at INTEGER,UNIQUE(event_id,channel,destination_ref,generation));
CREATE TABLE inbox(channel TEXT NOT NULL,source_id TEXT NOT NULL,content_id TEXT NOT NULL REFERENCES contents(id),state TEXT NOT NULL,acknowledged_at INTEGER,PRIMARY KEY(channel,source_id));
CREATE TABLE projections(namespace TEXT NOT NULL,scope_key TEXT NOT NULL,projection_key TEXT NOT NULL,source_sequence INTEGER NOT NULL,expires_at INTEGER,content_id TEXT NOT NULL REFERENCES contents(id),last_error TEXT,PRIMARY KEY(namespace,scope_key,projection_key));
CREATE TABLE growth_items(snapshot_id TEXT NOT NULL REFERENCES growth_snapshots(id),item_id TEXT NOT NULL,parent_id TEXT,kind TEXT NOT NULL,relative_path TEXT,label TEXT NOT NULL,metrics_json TEXT,production_files INTEGER,test_files INTEGER,test_cases INTEGER,bytes INTEGER,PRIMARY KEY(snapshot_id,item_id),FOREIGN KEY(snapshot_id,parent_id) REFERENCES growth_items(snapshot_id,item_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE growth_edges(snapshot_id TEXT NOT NULL,source_item_id TEXT NOT NULL,target_item_id TEXT NOT NULL,kind TEXT NOT NULL,weight REAL,evidence_id TEXT REFERENCES evidence(id),PRIMARY KEY(snapshot_id,source_item_id,target_item_id,kind),FOREIGN KEY(snapshot_id,source_item_id) REFERENCES growth_items(snapshot_id,item_id),FOREIGN KEY(snapshot_id,target_item_id) REFERENCES growth_items(snapshot_id,item_id));
CREATE TABLE growth_signals(snapshot_id TEXT NOT NULL,signal_key TEXT NOT NULL,item_id TEXT NOT NULL,type TEXT NOT NULL,level TEXT NOT NULL,value TEXT,evidence_id TEXT REFERENCES evidence(id),PRIMARY KEY(snapshot_id,signal_key),FOREIGN KEY(snapshot_id,item_id) REFERENCES growth_items(snapshot_id,item_id));
CREATE INDEX objects_scope_kind ON objects(project_id,kind,archived_at,updated_at,id);
CREATE VIRTUAL TABLE object_search USING fts5(terms,content='',contentless_delete=1,detail=none);
CREATE INDEX events_subject_sequence ON events(subject_id,sequence);
CREATE INDEX log_chunks_order ON log_chunks(run_id,stream,byte_offset);
CREATE INDEX outbox_delivery ON outbox(state,next_attempt_at);
CREATE TABLE projects(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL DEFAULT 'project' CHECK(object_kind='project'),project_id TEXT,name TEXT NOT NULL, type TEXT, priority TEXT, description TEXT, hidden INTEGER NOT NULL DEFAULT 0 CHECK(hidden IN (0,1)), pinned_at INTEGER,UNIQUE(id,project_id),FOREIGN KEY(id,object_kind) REFERENCES objects(id,kind),FOREIGN KEY(id,project_id) REFERENCES objects(id,project_id));
CREATE TRIGGER projects_scope_insert BEFORE INSERT ON projects WHEN NOT EXISTS(SELECT 1 FROM objects WHERE id=NEW.id AND project_id IS NEW.project_id) BEGIN SELECT RAISE(ABORT,'scope_mismatch'); END;
CREATE TRIGGER projects_scope_update BEFORE UPDATE OF project_id ON projects WHEN NEW.project_id IS NOT OLD.project_id BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;
CREATE INDEX projects_scope ON projects(project_id);
CREATE TABLE roadmap_nodes(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL DEFAULT 'roadmap_node' CHECK(object_kind='roadmap_node'),project_id TEXT NOT NULL,local_node_id TEXT NOT NULL, title TEXT NOT NULL, description TEXT, stage TEXT, order_key REAL NOT NULL DEFAULT 0, status TEXT NOT NULL, agent_cli TEXT, agent_prompt_content_id TEXT REFERENCES contents(id), completed_at INTEGER,UNIQUE(id,project_id),FOREIGN KEY(id,object_kind) REFERENCES objects(id,kind),FOREIGN KEY(id,project_id) REFERENCES objects(id,project_id),UNIQUE(project_id,local_node_id));
CREATE TRIGGER roadmap_nodes_scope_insert BEFORE INSERT ON roadmap_nodes WHEN NOT EXISTS(SELECT 1 FROM objects WHERE id=NEW.id AND project_id IS NEW.project_id) BEGIN SELECT RAISE(ABORT,'scope_mismatch'); END;
CREATE TRIGGER roadmap_nodes_scope_update BEFORE UPDATE OF project_id ON roadmap_nodes WHEN NEW.project_id IS NOT OLD.project_id BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;
CREATE INDEX roadmap_nodes_scope ON roadmap_nodes(project_id);
CREATE TABLE file_bindings(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL DEFAULT 'file_binding' CHECK(object_kind='file_binding'),project_id TEXT NOT NULL,role TEXT NOT NULL, relative_path TEXT NOT NULL, accepted_hash TEXT, exported_revision INTEGER, pending_revision INTEGER, last_error TEXT,UNIQUE(id,project_id),FOREIGN KEY(id,object_kind) REFERENCES objects(id,kind),FOREIGN KEY(id,project_id) REFERENCES objects(id,project_id),UNIQUE(project_id,role,relative_path));
CREATE TRIGGER file_bindings_scope_insert BEFORE INSERT ON file_bindings WHEN NOT EXISTS(SELECT 1 FROM objects WHERE id=NEW.id AND project_id IS NEW.project_id) BEGIN SELECT RAISE(ABORT,'scope_mismatch'); END;
CREATE TRIGGER file_bindings_scope_update BEFORE UPDATE OF project_id ON file_bindings WHEN NEW.project_id IS NOT OLD.project_id BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;
CREATE INDEX file_bindings_scope ON file_bindings(project_id);
CREATE TABLE documents(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL DEFAULT 'document' CHECK(object_kind='document'),project_id TEXT NOT NULL,file_binding_id TEXT NOT NULL REFERENCES file_bindings(id), role TEXT NOT NULL, status TEXT NOT NULL, solves TEXT, last_reviewed_at INTEGER,UNIQUE(id,project_id),FOREIGN KEY(id,object_kind) REFERENCES objects(id,kind),FOREIGN KEY(id,project_id) REFERENCES objects(id,project_id),FOREIGN KEY(file_binding_id,project_id) REFERENCES file_bindings(id,project_id));
CREATE TRIGGER documents_scope_insert BEFORE INSERT ON documents WHEN NOT EXISTS(SELECT 1 FROM objects WHERE id=NEW.id AND project_id IS NEW.project_id) BEGIN SELECT RAISE(ABORT,'scope_mismatch'); END;
CREATE TRIGGER documents_scope_update BEFORE UPDATE OF project_id ON documents WHEN NEW.project_id IS NOT OLD.project_id BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;
CREATE INDEX documents_scope ON documents(project_id);
CREATE TABLE assets(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL DEFAULT 'asset' CHECK(object_kind='asset'),project_id TEXT NOT NULL,name TEXT NOT NULL, content_id TEXT REFERENCES contents(id), file_binding_id TEXT REFERENCES file_bindings(id), origin TEXT, sha256 TEXT,UNIQUE(id,project_id),FOREIGN KEY(id,object_kind) REFERENCES objects(id,kind),FOREIGN KEY(id,project_id) REFERENCES objects(id,project_id),FOREIGN KEY(file_binding_id,project_id) REFERENCES file_bindings(id,project_id),CHECK((content_id IS NULL) <> (file_binding_id IS NULL)));
CREATE TRIGGER assets_scope_insert BEFORE INSERT ON assets WHEN NOT EXISTS(SELECT 1 FROM objects WHERE id=NEW.id AND project_id IS NEW.project_id) BEGIN SELECT RAISE(ABORT,'scope_mismatch'); END;
CREATE TRIGGER assets_scope_update BEFORE UPDATE OF project_id ON assets WHEN NEW.project_id IS NOT OLD.project_id BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;
CREATE INDEX assets_scope ON assets(project_id);
CREATE TABLE integrations(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL DEFAULT 'integration' CHECK(object_kind='integration'),project_id TEXT,kind TEXT NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL, package_version_id TEXT REFERENCES package_versions(id), config_content_id TEXT REFERENCES contents(id), secret_ref TEXT, health_content_id TEXT REFERENCES contents(id),UNIQUE(id,project_id),FOREIGN KEY(id,object_kind) REFERENCES objects(id,kind),FOREIGN KEY(id,project_id) REFERENCES objects(id,project_id));
CREATE TRIGGER integrations_scope_insert BEFORE INSERT ON integrations WHEN NOT EXISTS(SELECT 1 FROM objects WHERE id=NEW.id AND project_id IS NEW.project_id) BEGIN SELECT RAISE(ABORT,'scope_mismatch'); END;
CREATE TRIGGER integrations_scope_update BEFORE UPDATE OF project_id ON integrations WHEN NEW.project_id IS NOT OLD.project_id BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;
CREATE INDEX integrations_scope ON integrations(project_id);
CREATE TABLE package_versions(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL DEFAULT 'package_version' CHECK(object_kind='package_version'),project_id TEXT,package_key TEXT NOT NULL, version TEXT NOT NULL, source TEXT NOT NULL, digest TEXT NOT NULL, installed_relative_path TEXT NOT NULL,UNIQUE(id,project_id),FOREIGN KEY(id,object_kind) REFERENCES objects(id,kind),FOREIGN KEY(id,project_id) REFERENCES objects(id,project_id),UNIQUE(package_key,version,digest));
CREATE TRIGGER package_versions_scope_insert BEFORE INSERT ON package_versions WHEN NOT EXISTS(SELECT 1 FROM objects WHERE id=NEW.id AND project_id IS NEW.project_id) BEGIN SELECT RAISE(ABORT,'scope_mismatch'); END;
CREATE TRIGGER package_versions_scope_update BEFORE UPDATE OF project_id ON package_versions WHEN NEW.project_id IS NOT OLD.project_id BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;
CREATE INDEX package_versions_scope ON package_versions(project_id);
CREATE TABLE conversations(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL DEFAULT 'conversation' CHECK(object_kind='conversation'),project_id TEXT NOT NULL,parent_conversation_id TEXT REFERENCES conversations(id), node_id TEXT REFERENCES roadmap_nodes(id), mode TEXT NOT NULL, status TEXT NOT NULL, title TEXT NOT NULL,UNIQUE(id,project_id),FOREIGN KEY(id,object_kind) REFERENCES objects(id,kind),FOREIGN KEY(id,project_id) REFERENCES objects(id,project_id),FOREIGN KEY(parent_conversation_id,project_id) REFERENCES conversations(id,project_id),FOREIGN KEY(node_id,project_id) REFERENCES roadmap_nodes(id,project_id));
CREATE TRIGGER conversations_scope_insert BEFORE INSERT ON conversations WHEN NOT EXISTS(SELECT 1 FROM objects WHERE id=NEW.id AND project_id IS NEW.project_id) BEGIN SELECT RAISE(ABORT,'scope_mismatch'); END;
CREATE TRIGGER conversations_scope_update BEFORE UPDATE OF project_id ON conversations WHEN NEW.project_id IS NOT OLD.project_id BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;
CREATE INDEX conversations_scope ON conversations(project_id);
CREATE TABLE messages(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL DEFAULT 'message' CHECK(object_kind='message'),project_id TEXT NOT NULL,conversation_id TEXT NOT NULL REFERENCES conversations(id), sequence INTEGER NOT NULL, role TEXT NOT NULL, content_id TEXT NOT NULL REFERENCES contents(id), turn_id TEXT REFERENCES turns(id),UNIQUE(id,project_id),FOREIGN KEY(id,object_kind) REFERENCES objects(id,kind),FOREIGN KEY(id,project_id) REFERENCES objects(id,project_id),FOREIGN KEY(conversation_id,project_id) REFERENCES conversations(id,project_id),FOREIGN KEY(turn_id,project_id) REFERENCES turns(id,project_id),UNIQUE(conversation_id,sequence));
CREATE TRIGGER messages_scope_insert BEFORE INSERT ON messages WHEN NOT EXISTS(SELECT 1 FROM objects WHERE id=NEW.id AND project_id IS NEW.project_id) BEGIN SELECT RAISE(ABORT,'scope_mismatch'); END;
CREATE TRIGGER messages_scope_update BEFORE UPDATE OF project_id ON messages WHEN NEW.project_id IS NOT OLD.project_id BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;
CREATE INDEX messages_scope ON messages(project_id);
CREATE TABLE tasks(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL DEFAULT 'task' CHECK(object_kind='task'),project_id TEXT NOT NULL,conversation_id TEXT NOT NULL REFERENCES conversations(id), node_id TEXT REFERENCES roadmap_nodes(id), original_request_content_id TEXT NOT NULL REFERENCES contents(id), criteria_content_id TEXT REFERENCES contents(id), status TEXT NOT NULL,UNIQUE(id,project_id),FOREIGN KEY(id,object_kind) REFERENCES objects(id,kind),FOREIGN KEY(id,project_id) REFERENCES objects(id,project_id),FOREIGN KEY(conversation_id,project_id) REFERENCES conversations(id,project_id),FOREIGN KEY(node_id,project_id) REFERENCES roadmap_nodes(id,project_id));
CREATE TRIGGER tasks_scope_insert BEFORE INSERT ON tasks WHEN NOT EXISTS(SELECT 1 FROM objects WHERE id=NEW.id AND project_id IS NEW.project_id) BEGIN SELECT RAISE(ABORT,'scope_mismatch'); END;
CREATE TRIGGER tasks_scope_update BEFORE UPDATE OF project_id ON tasks WHEN NEW.project_id IS NOT OLD.project_id BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;
CREATE INDEX tasks_scope ON tasks(project_id);
CREATE TABLE turns(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL DEFAULT 'turn' CHECK(object_kind='turn'),project_id TEXT NOT NULL,task_id TEXT NOT NULL REFERENCES tasks(id), sequence INTEGER NOT NULL, request_content_id TEXT NOT NULL REFERENCES contents(id), outcome TEXT, summary_content_id TEXT REFERENCES contents(id), started_at INTEGER NOT NULL, finished_at INTEGER,UNIQUE(id,project_id),FOREIGN KEY(id,object_kind) REFERENCES objects(id,kind),FOREIGN KEY(id,project_id) REFERENCES objects(id,project_id),FOREIGN KEY(task_id,project_id) REFERENCES tasks(id,project_id),UNIQUE(task_id,sequence));
CREATE TRIGGER turns_scope_insert BEFORE INSERT ON turns WHEN NOT EXISTS(SELECT 1 FROM objects WHERE id=NEW.id AND project_id IS NEW.project_id) BEGIN SELECT RAISE(ABORT,'scope_mismatch'); END;
CREATE TRIGGER turns_scope_update BEFORE UPDATE OF project_id ON turns WHEN NEW.project_id IS NOT OLD.project_id BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;
CREATE INDEX turns_scope ON turns(project_id);
CREATE TABLE runs(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL DEFAULT 'run' CHECK(object_kind='run'),project_id TEXT NOT NULL,task_id TEXT NOT NULL REFERENCES tasks(id), turn_id TEXT REFERENCES turns(id), conversation_id TEXT NOT NULL REFERENCES conversations(id), location_id TEXT NOT NULL REFERENCES project_locations(id), run_kind TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES actors(id), command_content_id TEXT REFERENCES contents(id), prompt_content_id TEXT REFERENCES contents(id), status TEXT NOT NULL, started_at INTEGER NOT NULL, finished_at INTEGER, duration_ms INTEGER, exit_code INTEGER, input_tokens INTEGER, cached_input_tokens INTEGER, output_tokens INTEGER, reasoning_output_tokens INTEGER, total_tokens INTEGER, usage_json TEXT,UNIQUE(id,project_id),FOREIGN KEY(id,object_kind) REFERENCES objects(id,kind),FOREIGN KEY(id,project_id) REFERENCES objects(id,project_id),FOREIGN KEY(task_id,project_id) REFERENCES tasks(id,project_id),FOREIGN KEY(turn_id,project_id) REFERENCES turns(id,project_id),FOREIGN KEY(conversation_id,project_id) REFERENCES conversations(id,project_id),FOREIGN KEY(location_id,project_id) REFERENCES project_locations(id,project_id));
CREATE TRIGGER runs_scope_insert BEFORE INSERT ON runs WHEN NOT EXISTS(SELECT 1 FROM objects WHERE id=NEW.id AND project_id IS NEW.project_id) BEGIN SELECT RAISE(ABORT,'scope_mismatch'); END;
CREATE TRIGGER runs_scope_update BEFORE UPDATE OF project_id ON runs WHEN NEW.project_id IS NOT OLD.project_id BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;
CREATE INDEX runs_scope ON runs(project_id);
CREATE TABLE evidence(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL DEFAULT 'evidence' CHECK(object_kind='evidence'),project_id TEXT NOT NULL,run_id TEXT REFERENCES runs(id), type TEXT NOT NULL, source_actor_id TEXT NOT NULL REFERENCES actors(id), content_id TEXT REFERENCES contents(id), file_binding_id TEXT REFERENCES file_bindings(id), observed_at INTEGER NOT NULL, source_revision INTEGER,UNIQUE(id,project_id),FOREIGN KEY(id,object_kind) REFERENCES objects(id,kind),FOREIGN KEY(id,project_id) REFERENCES objects(id,project_id),FOREIGN KEY(run_id,project_id) REFERENCES runs(id,project_id),FOREIGN KEY(file_binding_id,project_id) REFERENCES file_bindings(id,project_id),CHECK(content_id IS NOT NULL OR file_binding_id IS NOT NULL));
CREATE TRIGGER evidence_scope_insert BEFORE INSERT ON evidence WHEN NOT EXISTS(SELECT 1 FROM objects WHERE id=NEW.id AND project_id IS NEW.project_id) BEGIN SELECT RAISE(ABORT,'scope_mismatch'); END;
CREATE TRIGGER evidence_scope_update BEFORE UPDATE OF project_id ON evidence WHEN NEW.project_id IS NOT OLD.project_id BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;
CREATE INDEX evidence_scope ON evidence(project_id);
CREATE TABLE verifications(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL DEFAULT 'verification' CHECK(object_kind='verification'),project_id TEXT NOT NULL,task_id TEXT NOT NULL REFERENCES tasks(id), run_id TEXT REFERENCES runs(id), verifier_actor_id TEXT NOT NULL REFERENCES actors(id), claim TEXT NOT NULL, result TEXT NOT NULL, evidence_id TEXT NOT NULL REFERENCES evidence(id), verified_at INTEGER NOT NULL,UNIQUE(id,project_id),FOREIGN KEY(id,object_kind) REFERENCES objects(id,kind),FOREIGN KEY(id,project_id) REFERENCES objects(id,project_id),FOREIGN KEY(task_id,project_id) REFERENCES tasks(id,project_id),FOREIGN KEY(run_id,project_id) REFERENCES runs(id,project_id),FOREIGN KEY(evidence_id,project_id) REFERENCES evidence(id,project_id));
CREATE TRIGGER verifications_scope_insert BEFORE INSERT ON verifications WHEN NOT EXISTS(SELECT 1 FROM objects WHERE id=NEW.id AND project_id IS NEW.project_id) BEGIN SELECT RAISE(ABORT,'scope_mismatch'); END;
CREATE TRIGGER verifications_scope_update BEFORE UPDATE OF project_id ON verifications WHEN NEW.project_id IS NOT OLD.project_id BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;
CREATE INDEX verifications_scope ON verifications(project_id);
CREATE TABLE reports(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL DEFAULT 'report' CHECK(object_kind='report'),project_id TEXT NOT NULL,turn_id TEXT NOT NULL REFERENCES turns(id), run_id TEXT REFERENCES runs(id), schema_version INTEGER NOT NULL, content_id TEXT NOT NULL REFERENCES contents(id), availability TEXT NOT NULL, validation_error TEXT,UNIQUE(id,project_id),FOREIGN KEY(id,object_kind) REFERENCES objects(id,kind),FOREIGN KEY(id,project_id) REFERENCES objects(id,project_id),FOREIGN KEY(turn_id,project_id) REFERENCES turns(id,project_id),FOREIGN KEY(run_id,project_id) REFERENCES runs(id,project_id));
CREATE TRIGGER reports_scope_insert BEFORE INSERT ON reports WHEN NOT EXISTS(SELECT 1 FROM objects WHERE id=NEW.id AND project_id IS NEW.project_id) BEGIN SELECT RAISE(ABORT,'scope_mismatch'); END;
CREATE TRIGGER reports_scope_update BEFORE UPDATE OF project_id ON reports WHEN NEW.project_id IS NOT OLD.project_id BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;
CREATE INDEX reports_scope ON reports(project_id);
CREATE TABLE workflow_loops(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL DEFAULT 'workflow_loop' CHECK(object_kind='workflow_loop'),project_id TEXT NOT NULL,task_id TEXT NOT NULL REFERENCES tasks(id), sequence INTEGER NOT NULL, goal TEXT NOT NULL, status TEXT NOT NULL, planner_run_id TEXT REFERENCES runs(id), builder_run_id TEXT REFERENCES runs(id), verifier_run_id TEXT REFERENCES runs(id), scoring_content_id TEXT REFERENCES contents(id),UNIQUE(id,project_id),FOREIGN KEY(id,object_kind) REFERENCES objects(id,kind),FOREIGN KEY(id,project_id) REFERENCES objects(id,project_id),FOREIGN KEY(task_id,project_id) REFERENCES tasks(id,project_id),FOREIGN KEY(planner_run_id,project_id) REFERENCES runs(id,project_id),FOREIGN KEY(builder_run_id,project_id) REFERENCES runs(id,project_id),FOREIGN KEY(verifier_run_id,project_id) REFERENCES runs(id,project_id),UNIQUE(task_id,sequence));
CREATE TRIGGER workflow_loops_scope_insert BEFORE INSERT ON workflow_loops WHEN NOT EXISTS(SELECT 1 FROM objects WHERE id=NEW.id AND project_id IS NEW.project_id) BEGIN SELECT RAISE(ABORT,'scope_mismatch'); END;
CREATE TRIGGER workflow_loops_scope_update BEFORE UPDATE OF project_id ON workflow_loops WHEN NEW.project_id IS NOT OLD.project_id BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;
CREATE INDEX workflow_loops_scope ON workflow_loops(project_id);
CREATE TABLE memories(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL DEFAULT 'memory' CHECK(object_kind='memory'),project_id TEXT,category TEXT NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL, confidence REAL NOT NULL DEFAULT 0 CHECK(confidence BETWEEN 0 AND 1), content_id TEXT NOT NULL REFERENCES contents(id), valid_until INTEGER, external_source TEXT, external_revision TEXT, canonical_hash TEXT,UNIQUE(id,project_id),FOREIGN KEY(id,object_kind) REFERENCES objects(id,kind),FOREIGN KEY(id,project_id) REFERENCES objects(id,project_id));
CREATE TRIGGER memories_scope_insert BEFORE INSERT ON memories WHEN NOT EXISTS(SELECT 1 FROM objects WHERE id=NEW.id AND project_id IS NEW.project_id) BEGIN SELECT RAISE(ABORT,'scope_mismatch'); END;
CREATE TRIGGER memories_scope_update BEFORE UPDATE OF project_id ON memories WHEN NEW.project_id IS NOT OLD.project_id BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;
CREATE INDEX memories_scope ON memories(project_id);
CREATE TABLE learning_events(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL DEFAULT 'learning_event' CHECK(object_kind='learning_event'),project_id TEXT,source_object_id TEXT NOT NULL REFERENCES objects(id), event_type TEXT NOT NULL, summary TEXT NOT NULL, occurred_at INTEGER NOT NULL, source_revision INTEGER NOT NULL,UNIQUE(id,project_id),FOREIGN KEY(id,object_kind) REFERENCES objects(id,kind),FOREIGN KEY(id,project_id) REFERENCES objects(id,project_id),UNIQUE(source_object_id,event_type,source_revision));
CREATE TRIGGER learning_events_scope_insert BEFORE INSERT ON learning_events WHEN NOT EXISTS(SELECT 1 FROM objects WHERE id=NEW.id AND project_id IS NEW.project_id) BEGIN SELECT RAISE(ABORT,'scope_mismatch'); END;
CREATE TRIGGER learning_events_scope_update BEFORE UPDATE OF project_id ON learning_events WHEN NEW.project_id IS NOT OLD.project_id BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;
CREATE INDEX learning_events_scope ON learning_events(project_id);
CREATE TABLE lessons(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL DEFAULT 'lesson' CHECK(object_kind='lesson'),project_id TEXT,status TEXT NOT NULL, summary TEXT NOT NULL, applies_when TEXT, does_not_apply_when TEXT, do_this TEXT, avoid_this TEXT, verification TEXT, confidence REAL NOT NULL DEFAULT 0 CHECK(confidence BETWEEN 0 AND 1),UNIQUE(id,project_id),FOREIGN KEY(id,object_kind) REFERENCES objects(id,kind),FOREIGN KEY(id,project_id) REFERENCES objects(id,project_id));
CREATE TRIGGER lessons_scope_insert BEFORE INSERT ON lessons WHEN NOT EXISTS(SELECT 1 FROM objects WHERE id=NEW.id AND project_id IS NEW.project_id) BEGIN SELECT RAISE(ABORT,'scope_mismatch'); END;
CREATE TRIGGER lessons_scope_update BEFORE UPDATE OF project_id ON lessons WHEN NEW.project_id IS NOT OLD.project_id BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;
CREATE INDEX lessons_scope ON lessons(project_id);
