CREATE TABLE policy_uses(id TEXT PRIMARY KEY,object_kind TEXT NOT NULL DEFAULT 'policy_use' CHECK(object_kind='policy_use'),project_id TEXT NOT NULL,policy_id TEXT NOT NULL REFERENCES policies(id), policy_revision INTEGER NOT NULL, lesson_id TEXT REFERENCES lessons(id), lesson_revision INTEGER, run_id TEXT NOT NULL REFERENCES runs(id), purpose TEXT NOT NULL,UNIQUE(id,project_id),FOREIGN KEY(id,object_kind) REFERENCES objects(id,kind),FOREIGN KEY(id,project_id) REFERENCES objects(id,project_id),FOREIGN KEY(run_id,project_id) REFERENCES runs(id,project_id),FOREIGN KEY(policy_id,policy_revision) REFERENCES object_revisions(object_id,revision), FOREIGN KEY(lesson_id,lesson_revision) REFERENCES object_revisions(object_id,revision));
