CREATE TRIGGER roadmap_dependency_scope BEFORE INSERT ON roadmap_dependencies WHEN (SELECT project_id FROM roadmap_nodes WHERE id=NEW.node_id) IS NOT (SELECT project_id FROM roadmap_nodes WHERE id=NEW.dependency_id) BEGIN SELECT RAISE(ABORT,'scope_mismatch'); END;
CREATE TRIGGER object_scope_immutable BEFORE UPDATE OF project_id,kind ON objects WHEN NEW.project_id IS NOT OLD.project_id OR NEW.kind<>OLD.kind BEGIN SELECT RAISE(ABORT,'immutable_identity'); END;